import{_ as i,o as n,c as o,a3 as a,j as e,a as r}from"./chunks/framework.B5WAEDB7.js";const f=JSON.parse('{"title":"Common Error Messages","description":"ApptiveGrid error messages verbatim, with cause and solution.","frontmatter":{"title":"Common Error Messages","description":"ApptiveGrid error messages verbatim, with cause and solution."},"headers":[],"relativePath":"en/fehlerbehebung/haeufige-fehlermeldungen.md","filePath":"en/fehlerbehebung/haeufige-fehlermeldungen.md","lastUpdated":1788446198000}'),s={name:"en/fehlerbehebung/haeufige-fehlermeldungen.md"};function l(h,t,d,u,c,p){return n(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="common-error-messages" tabindex="-1">Common Error Messages <a class="header-anchor" href="#common-error-messages" aria-label="Permalink to &quot;Common Error Messages&quot;">​</a></h1><p>The messages are listed here <strong>verbatim</strong>, so you can search for them.</p><nav class="table-of-contents"><ul><li><a href="#data-and-entries">Data and entries</a><ul><li><a href="#cannot-delete-this-entry-is-still-referenced-elsewhere">Cannot delete. This entry is still referenced elsewhere.</a></li><li><a href="#cannot-delete-this-entry-is-still-referenced-by-reference">Cannot delete. This entry is still referenced by {reference}.</a></li><li><a href="#cannot-change-this-field-is-used-in-a-filter">Cannot change. This field is used in a filter.</a></li><li><a href="#links-to-grids-that-are-already-linked-elsewhere-are-not-yet-possible">Links to Grids that are already linked elsewhere are not yet possible.</a></li><li><a href="#the-name-already-exists">The name already exists</a></li><li><a href="#the-name-can-be-a-maximum-of-max-characters-long">The name can be a maximum of {max} characters long.</a></li><li><a href="#no-matching-entry-found">No matching entry found.</a></li><li><a href="#row-filtered">Row filtered</a></li><li><a href="#this-grid-has-been-updated">This Grid has been updated</a></li></ul></li><li><a href="#input">Input</a><ul><li><a href="#please-fill-in-this-required-field">Please fill in this required field.</a></li><li><a href="#only-numbers-0-9-are-allowed">Only numbers (0-9) are allowed</a></li><li><a href="#only-floating-point-numbers-are-allowed">Only floating point numbers are allowed</a></li><li><a href="#a-valid-e-mail-address-is-required">A valid e-mail address is required</a></li><li><a href="#please-enter-a-valid-phone-number">Please enter a valid phone number</a></li><li><a href="#an-international-dialing-code-is-required-e-g-49">An international dialing code is required (e.g. +49)</a></li><li><a href="#please-enter-a-valid-url">Please enter a valid URL</a></li><li><a href="#must-be-in-the-format-latitude-longitude-e-g-50-12-6-543">Must be in the format Latitude, Longitude (e.g. 50.12,6.543)</a></li><li><a href="#please-fill-in-the-required-subfields">Please fill in the required subfields</a></li><li><a href="#unrecognized-date-format">Unrecognized date format:</a></li><li><a href="#the-option-must-not-be-empty-·-the-option-must-not-be-a-duplicate">The option must not be empty · The option must not be a duplicate</a></li></ul></li><li><a href="#filters">Filters</a><ul><li><a href="#all-existing-filters-must-be-valid">All existing filters must be valid</a></li><li><a href="#filter-conditions-can-only-be-nested-3-levels-deep">Filter conditions can only be nested 3 levels deep</a></li></ul></li><li><a href="#expressions-and-formulas">Expressions and formulas</a><ul><li><a href="#asstring-class-has-no-function-named">ASString class has no function named …</a></li><li><a href="#function-needs-1-arguments">function needs 1 arguments</a></li><li><a href="#unexpected-token">Unexpected token …</a></li><li><a href="#no-field-with-id">No field with id …</a></li><li><a href="#no-message-but-no-result-either">No message, but no result either</a></li></ul></li><li><a href="#sign-in-and-registration">Sign-in and registration</a><ul><li><a href="#login-failed">Login failed</a></li><li><a href="#session-expired">Session expired</a></li><li><a href="#approval-required">Approval required</a></li><li><a href="#we-were-unable-to-create-an-account-with-the-email-and-password-you-entered">We were unable to create an account with the email and password you entered.</a></li><li><a href="#we-could-not-reset-the-password">We could not reset the password.</a></li><li><a href="#required-·-min-3-characters-·-use-at-least-8-characters-·-please-enter-a-valid-email">Required · Min 3 characters · Use at least 8 characters · Please enter a valid email</a></li></ul></li><li><a href="#access-and-sharing">Access and sharing</a><ul><li><a href="#you-no-longer-have-access-to-this-space">You no longer have access to this Space.</a></li><li><a href="#this-space-has-been-deleted">This Space has been deleted</a></li><li><a href="#not-allowed">Not allowed</a></li><li><a href="#access-to-this-form-is-restricted">Access to this form is restricted.</a></li><li><a href="#this-view-is-no-longer-accessible">This view is no longer accessible.</a></li><li><a href="#this-space-is-already-shared-with-this-user">This Space is already shared with this user</a></li><li><a href="#spaces-cannot-be-shared-with-themselves">Spaces cannot be shared with themselves</a></li><li><a href="#no-user-exists-with-the-e-mail">No user exists with the e-mail</a></li><li><a href="#exceeding-the-licensed-seats-on-your-plan">Exceeding the licensed seats on your plan</a></li></ul></li><li><a href="#flows">Flows</a><ul><li><a href="#flow-still-has-errors">Flow still has errors</a></li><li><a href="#no-previous-run-was-found">No previous run was found.</a></li><li><a href="#there-s-no-custom-ui-set-up-for-this-step-if-you-need-a-ui-you-can-add-it-in-the-flow-editor">There&#39;s no custom UI set up for this step. If you need a UI, you can add it in the Flow Editor.</a></li><li><a href="#this-process-step-could-not-be-loaded">This process step could not be loaded</a></li><li><a href="#javascript-could-not-be-generated">JavaScript could not be generated</a></li></ul></li><li><a href="#pages-and-portals">Pages and portals</a><ul><li><a href="#this-view-has-no-summable-numeric-columns">This view has no summable numeric columns</a></li><li><a href="#this-view-has-more-than-maxrows-rows-the-sum-only-covers-the-first-maxrows-rows">This view has more than {maxRows} rows. The sum only covers the first {maxRows} rows.</a></li><li><a href="#input-fields-without-a-name-or-id-are-not-included-in-the-flow-payload">Input fields without a name or id are not included in the Flow payload.</a></li><li><a href="#count-file-s-could-not-be-uploaded">{count} file(s) could not be uploaded</a></li><li><a href="#preview-error">Preview error</a></li></ul></li><li><a href="#forms-—-what-people-filling-them-out-see">Forms — what people filling them out see</a><ul><li><a href="#oops-error">Oops - Error</a></li><li><a href="#warning-potentially-risky-form">Warning: Potentially risky form</a></li><li><a href="#this-form-has-been-locked">This form has been locked</a></li><li><a href="#never-reveal-your-password">Never reveal your password.</a></li></ul></li><li><a href="#no-message-but-still-a-problem">No message, but still a problem</a></li><li><a href="#next">Next</a></li></ul></nav><h2 id="data-and-entries" tabindex="-1">Data and entries <a class="header-anchor" href="#data-and-entries" aria-label="Permalink to &quot;Data and entries&quot;">​</a></h2><h3 id="cannot-delete-this-entry-is-still-referenced-elsewhere" tabindex="-1">Cannot delete. This entry is still referenced elsewhere. <a class="header-anchor" href="#cannot-delete-this-entry-is-still-referenced-elsewhere" aria-label="Permalink to &quot;Cannot delete. This entry is still referenced elsewhere.&quot;">​</a></h3><h3 id="cannot-delete-this-entry-is-still-referenced-by-reference" tabindex="-1">Cannot delete. This entry is still referenced by {reference}. <a class="header-anchor" href="#cannot-delete-this-entry-is-still-referenced-by-reference" aria-label="Permalink to &quot;Cannot delete. This entry is still referenced by {reference}.&quot;">​</a></h3><p>Both messages have the same cause: the entry is connected to another entry via a link. The second variant additionally names <strong>which</strong> entry references it — so you can go straight there.</p><p><strong>Solution:</strong> First remove the links pointing to this entry. If the message doesn&#39;t name the referencing entry, a filtered view in the referencing Grid helps you find all affected entries.</p><p>This is a safeguard — it prevents dangling references. → <a href="/en/grids/verknuepfungen">Linking Grids</a></p><h3 id="cannot-change-this-field-is-used-in-a-filter" tabindex="-1">Cannot change. This field is used in a filter. <a class="header-anchor" href="#cannot-change-this-field-is-used-in-a-filter" aria-label="Permalink to &quot;Cannot change. This field is used in a filter.&quot;">​</a></h3><p>You&#39;re trying to change the type or name of a field that a filter points to.</p><p><strong>Solution:</strong> Remove the filter in the relevant view, change the field, then set the filter again. The filter can be in <strong>any</strong> view of the Grid, not just the one currently open.</p><h3 id="links-to-grids-that-are-already-linked-elsewhere-are-not-yet-possible" tabindex="-1">Links to Grids that are already linked elsewhere are not yet possible. <a class="header-anchor" href="#links-to-grids-that-are-already-linked-elsewhere-are-not-yet-possible" aria-label="Permalink to &quot;Links to Grids that are already linked elsewhere are not yet possible.&quot;">​</a></h3><p>You&#39;re trying to link to a Grid that is itself already linked somewhere else. Chains of links are not possible.</p><p><strong>Solution:</strong> Flatten your data model, link directly to the target Grid, or retrieve the value via <a href="/en/grids/berechnete-felder">Use linked value</a>. → <a href="/en/grids/verknuepfungen">Linking Grids</a></p><h3 id="the-name-already-exists" tabindex="-1">The name already exists <a class="header-anchor" href="#the-name-already-exists" aria-label="Permalink to &quot;The name already exists&quot;">​</a></h3><p>Field and Grid names must be unique.</p><h3 id="the-name-can-be-a-maximum-of-max-characters-long" tabindex="-1">The name can be a maximum of {max} characters long. <a class="header-anchor" href="#the-name-can-be-a-maximum-of-max-characters-long" aria-label="Permalink to &quot;The name can be a maximum of {max} characters long.&quot;">​</a></h3><p>Shorten the name.</p><h3 id="no-matching-entry-found" tabindex="-1">No matching entry found. <a class="header-anchor" href="#no-matching-entry-found" aria-label="Permalink to &quot;No matching entry found.&quot;">​</a></h3><p>There&#39;s no match in the selection dialog for a link.</p><p><strong>Common cause:</strong> The target view of the link is filtered, and the entry you&#39;re looking for is excluded by the filter. Check the target view&#39;s filter.</p><h3 id="row-filtered" tabindex="-1">Row filtered <a class="header-anchor" href="#row-filtered" aria-label="Permalink to &quot;Row filtered&quot;">​</a></h3><p>Not an error, but a notice: you&#39;ve changed an entry so that it no longer matches the view&#39;s filter, and it&#39;s now hidden.</p><p>The entry is <strong>not deleted</strong>. In an unfiltered view, it&#39;s still there.</p><h3 id="this-grid-has-been-updated" tabindex="-1">This Grid has been updated <a class="header-anchor" href="#this-grid-has-been-updated" aria-label="Permalink to &quot;This Grid has been updated&quot;">​</a></h3><p>Someone else has changed the Grid. Reload the view to see the current state.</p><hr><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><h3 id="please-fill-in-this-required-field" tabindex="-1">Please fill in this required field. <a class="header-anchor" href="#please-fill-in-this-required-field" aria-label="Permalink to &quot;Please fill in this required field.&quot;">​</a></h3><p>A field marked as required is empty.</p><h3 id="only-numbers-0-9-are-allowed" tabindex="-1">Only numbers (0-9) are allowed <a class="header-anchor" href="#only-numbers-0-9-are-allowed" aria-label="Permalink to &quot;Only numbers (0-9) are allowed&quot;">​</a></h3><p>The field is of type <strong>Number</strong> and only accepts whole numbers. For decimal places, use <strong>Decimal</strong> or <strong>Currency</strong> instead.</p><h3 id="only-floating-point-numbers-are-allowed" tabindex="-1">Only floating point numbers are allowed <a class="header-anchor" href="#only-floating-point-numbers-are-allowed" aria-label="Permalink to &quot;Only floating point numbers are allowed&quot;">​</a></h3><p>The value doesn&#39;t match the <strong>Decimal</strong> type. Check the decimal separator.</p><h3 id="a-valid-e-mail-address-is-required" tabindex="-1">A valid e-mail address is required <a class="header-anchor" href="#a-valid-e-mail-address-is-required" aria-label="Permalink to &quot;A valid e-mail address is required&quot;">​</a></h3><p>The input is not a valid e-mail address.</p><h3 id="please-enter-a-valid-phone-number" tabindex="-1">Please enter a valid phone number <a class="header-anchor" href="#please-enter-a-valid-phone-number" aria-label="Permalink to &quot;Please enter a valid phone number&quot;">​</a></h3><h3 id="an-international-dialing-code-is-required-e-g-49" tabindex="-1">An international dialing code is required (e.g. +49) <a class="header-anchor" href="#an-international-dialing-code-is-required-e-g-49" aria-label="Permalink to &quot;An international dialing code is required (e.g. +49)&quot;">​</a></h3><p>Phone numbers need a country code.</p><p><strong>Tip for form creators:</strong> Point this out in the field description, or incorrect entries will pile up.</p><h3 id="please-enter-a-valid-url" tabindex="-1">Please enter a valid URL <a class="header-anchor" href="#please-enter-a-valid-url" aria-label="Permalink to &quot;Please enter a valid URL&quot;">​</a></h3><p>Enter the full address, including <code>https://</code>.</p><h3 id="must-be-in-the-format-latitude-longitude-e-g-50-12-6-543" tabindex="-1">Must be in the format Latitude, Longitude (e.g. 50.12,6.543) <a class="header-anchor" href="#must-be-in-the-format-latitude-longitude-e-g-50-12-6-543" aria-label="Permalink to &quot;Must be in the format Latitude, Longitude (e.g. 50.12,6.543)&quot;">​</a></h3><p>Geocoordinates as two numbers separated by a comma; the decimal separator is a period.</p><h3 id="please-fill-in-the-required-subfields" tabindex="-1">Please fill in the required subfields <a class="header-anchor" href="#please-fill-in-the-required-subfields" aria-label="Permalink to &quot;Please fill in the required subfields&quot;">​</a></h3><p>An address field is incomplete.</p>',47),e("h3",{date:"",id:"unrecognized-date-format",tabindex:"-1"},[r("Unrecognized date format: "),e("a",{class:"header-anchor",href:"#unrecognized-date-format","aria-label":'Permalink to "Unrecognized date format: {date}"'},"​")],-1),a('<p>The entered or imported date can&#39;t be read. This commonly happens during <a href="/en/grids/csv-import">CSV import</a>.</p><h3 id="the-option-must-not-be-empty-·-the-option-must-not-be-a-duplicate" tabindex="-1">The option must not be empty · The option must not be a duplicate <a class="header-anchor" href="#the-option-must-not-be-empty-·-the-option-must-not-be-a-duplicate" aria-label="Permalink to &quot;The option must not be empty · The option must not be a duplicate&quot;">​</a></h3><p>Applies to the option list of <strong>Single Select</strong> and <strong>Multiple Select</strong>.</p><hr><h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h2><h3 id="all-existing-filters-must-be-valid" tabindex="-1">All existing filters must be valid <a class="header-anchor" href="#all-existing-filters-must-be-valid" aria-label="Permalink to &quot;All existing filters must be valid&quot;">​</a></h3><p>A filter condition is incomplete. Complete it or remove it — until then, the filter has no effect.</p><h3 id="filter-conditions-can-only-be-nested-3-levels-deep" tabindex="-1">Filter conditions can only be nested 3 levels deep <a class="header-anchor" href="#filter-conditions-can-only-be-nested-3-levels-deep" aria-label="Permalink to &quot;Filter conditions can only be nested 3 levels deep&quot;">​</a></h3><p>You&#39;ve reached the maximum nesting depth.</p><p><strong>Solution:</strong> Create a helper field of type <strong>Formula</strong> or <strong>Checkmark</strong> that captures the complex condition, and filter on that. → <a href="/en/ansichten/filtern-sortieren-gruppieren">Filtering, Sorting, Grouping</a></p><hr><h2 id="expressions-and-formulas" tabindex="-1">Expressions and formulas <a class="header-anchor" href="#expressions-and-formulas" aria-label="Permalink to &quot;Expressions and formulas&quot;">​</a></h2><p>The expression editor&#39;s messages are in English and name internal type names such as <em>ASString</em>.</p><h3 id="asstring-class-has-no-function-named" tabindex="-1">ASString class has no function named … <a class="header-anchor" href="#asstring-class-has-no-function-named" aria-label="Permalink to &quot;ASString class has no function named …&quot;">​</a></h3><p>This function doesn&#39;t exist for this value type. Most common cause: the expression yields a different type than expected at this point — after <code>.isEmpty()</code>, for example, it&#39;s a boolean, not text anymore.</p><p><strong>Solution:</strong> Check the displayed type (<em>Type: …</em> above the sample result) and use the functions for that type. → <a href="/en/referenz/apptivescript-funktionen">Function reference</a></p><h3 id="function-needs-1-arguments" tabindex="-1">function needs 1 arguments <a class="header-anchor" href="#function-needs-1-arguments" aria-label="Permalink to &quot;function needs 1 arguments&quot;">​</a></h3><p>The parentheses contain too few or too many values. The number required per function is listed in the <a href="/en/referenz/apptivescript-funktionen">function reference</a>.</p><h3 id="unexpected-token" tabindex="-1">Unexpected token … <a class="header-anchor" href="#unexpected-token" aria-label="Permalink to &quot;Unexpected token …&quot;">​</a></h3><p>The expression is incomplete or written incorrectly — a missing parenthesis, a trailing period, double quotes instead of single ones, or a comma used as a decimal separator. → <a href="/en/apptivescript/schreibweise">Syntax</a></p><h3 id="no-field-with-id" tabindex="-1">No field with id … <a class="header-anchor" href="#no-field-with-id" aria-label="Permalink to &quot;No field with id …&quot;">​</a></h3><p>The expression refers to a column that no longer exists. Re-insert the field using the picker.</p><h3 id="no-message-but-no-result-either" tabindex="-1">No message, but no result either <a class="header-anchor" href="#no-message-but-no-result-either" aria-label="Permalink to &quot;No message, but no result either&quot;">​</a></h3><p>The most common case doesn&#39;t produce an error message at all: an unknown name — a mistyped key, a misspelled function name — is treated as an empty value.</p><table tabindex="0"><thead><tr><th>Observation</th><th>Likely cause</th></tr></thead><tbody><tr><td>Formula column stays empty</td><td>Expression reaches into nothing, or an involved field is empty</td></tr><tr><td>Block <strong>never</strong> appears</td><td>Wrong key in the visibility rule</td></tr><tr><td>Block <strong>always</strong> appears</td><td>Faulty expression — a block stays visible on error</td></tr><tr><td>Filter returns nothing</td><td>Condition doesn&#39;t evaluate to a boolean</td></tr><tr><td>Placeholder in Flow text stays empty</td><td>The path to the value is wrong</td></tr></tbody></table><p>→ <a href="/en/apptivescript/werte-referenzieren">Referencing values</a></p><hr><h2 id="sign-in-and-registration" tabindex="-1">Sign-in and registration <a class="header-anchor" href="#sign-in-and-registration" aria-label="Permalink to &quot;Sign-in and registration&quot;">​</a></h2><p>These messages appear on the login page, before the application has even loaded.</p><h3 id="login-failed" tabindex="-1">Login failed <a class="header-anchor" href="#login-failed" aria-label="Permalink to &quot;Login failed&quot;">​</a></h3><blockquote><p><em>We were unable to log you in. Please check your email address and password.</em></p></blockquote><p>The email or password is wrong.</p><p><strong>Solution:</strong> Check what you entered; otherwise <a href="/en/erste-schritte/konto-und-anmeldung#forgot-password">reset your password</a>. If the account was created through Google, Apple, or Microsoft, there is no password — only the matching button will get you in.</p><h3 id="session-expired" tabindex="-1">Session expired <a class="header-anchor" href="#session-expired" aria-label="Permalink to &quot;Session expired&quot;">​</a></h3><blockquote><p><em>Your sign-in has expired or could not be completed.</em></p></blockquote><p>The login page was opened directly — from a bookmark, for instance — or sat open for more than half an hour.</p><p><strong>Solution:</strong> Choose <strong>Sign in again</strong>. The bookmark belongs on <code>app.apptivegrid.de</code>, not on the login page. → <a href="/en/erste-schritte/konto-und-anmeldung#session-expired">Session expired</a></p><h3 id="approval-required" tabindex="-1">Approval required <a class="header-anchor" href="#approval-required" aria-label="Permalink to &quot;Approval required&quot;">​</a></h3><p>This message comes from Microsoft, not from ApptiveGrid: your organization doesn&#39;t allow external applications to sign people in without administrator consent.</p><p><strong>Solution:</strong> Send the request to your administrator from the dialog, if it offers that. ApptiveGrid is cleared once in Microsoft Entra. → <a href="/en/erste-schritte/anmeldung-mit-microsoft">Signing in with Microsoft</a></p><h3 id="we-were-unable-to-create-an-account-with-the-email-and-password-you-entered" tabindex="-1">We were unable to create an account with the email and password you entered. <a class="header-anchor" href="#we-were-unable-to-create-an-account-with-the-email-and-password-you-entered" aria-label="Permalink to &quot;We were unable to create an account with the email and password you entered.&quot;">​</a></h3><p>Registration failed. The message doesn&#39;t name the reason — so also check whether an account already exists for that address.</p><p><strong>Solution:</strong> Check the details; if the account already exists, sign in or reset the password instead. → <a href="/en/erste-schritte/konto-und-anmeldung#creating-an-account">Creating an account</a></p><h3 id="we-could-not-reset-the-password" tabindex="-1">We could not reset the password. <a class="header-anchor" href="#we-could-not-reset-the-password" aria-label="Permalink to &quot;We could not reset the password.&quot;">​</a></h3><p>The reset link didn&#39;t work, or the password wasn&#39;t accepted.</p><p><strong>Solution:</strong> Trigger the reset again and use the link from the most recent email. → <a href="/en/erste-schritte/konto-und-anmeldung#forgot-password">Forgot password</a></p><h3 id="required-·-min-3-characters-·-use-at-least-8-characters-·-please-enter-a-valid-email" tabindex="-1">Required · Min 3 characters · Use at least 8 characters · Please enter a valid email <a class="header-anchor" href="#required-·-min-3-characters-·-use-at-least-8-characters-·-please-enter-a-valid-email" aria-label="Permalink to &quot;Required · Min 3 characters · Use at least 8 characters · Please enter a valid email&quot;">​</a></h3><p>Validation on the sign-up form. First and last name need at least 3 characters; the password needs at least 8 and at most 128 — beyond that the form reports <em>Use at most 128 characters</em>. The same password check applies when resetting it.</p><hr><h2 id="access-and-sharing" tabindex="-1">Access and sharing <a class="header-anchor" href="#access-and-sharing" aria-label="Permalink to &quot;Access and sharing&quot;">​</a></h2><h3 id="you-no-longer-have-access-to-this-space" tabindex="-1">You no longer have access to this Space. <a class="header-anchor" href="#you-no-longer-have-access-to-this-space" aria-label="Permalink to &quot;You no longer have access to this Space.&quot;">​</a></h3><p>Your permission has been revoked. Contact the owner of the Space.</p><h3 id="this-space-has-been-deleted" tabindex="-1">This Space has been deleted <a class="header-anchor" href="#this-space-has-been-deleted" aria-label="Permalink to &quot;This Space has been deleted&quot;">​</a></h3><h3 id="not-allowed" tabindex="-1">Not allowed <a class="header-anchor" href="#not-allowed" aria-label="Permalink to &quot;Not allowed&quot;">​</a></h3><p>Your <a href="/en/zusammenarbeit/rollen">role</a> doesn&#39;t permit this action.</p><h3 id="access-to-this-form-is-restricted" tabindex="-1">Access to this form is restricted. <a class="header-anchor" href="#access-to-this-form-is-restricted" aria-label="Permalink to &quot;Access to this form is restricted.&quot;">​</a></h3><p>The form link has an access restriction that you don&#39;t meet — for example <em>Any registered user</em> or <em>Anyone in this Space</em>.</p><p><strong>Solution:</strong> Sign in, or ask the form creator for access. → <a href="/en/zusammenarbeit/zugriff-beschraenken">Access to shared content</a></p><h3 id="this-view-is-no-longer-accessible" tabindex="-1">This view is no longer accessible. <a class="header-anchor" href="#this-view-is-no-longer-accessible" aria-label="Permalink to &quot;This view is no longer accessible.&quot;">​</a></h3><p>The shared view has been deleted, or sharing has been removed.</p><h3 id="this-space-is-already-shared-with-this-user" tabindex="-1">This Space is already shared with this user <a class="header-anchor" href="#this-space-is-already-shared-with-this-user" aria-label="Permalink to &quot;This Space is already shared with this user&quot;">​</a></h3><p>The person already has access. Change their role instead, in the <em>Shared with</em> list.</p><h3 id="spaces-cannot-be-shared-with-themselves" tabindex="-1">Spaces cannot be shared with themselves <a class="header-anchor" href="#spaces-cannot-be-shared-with-themselves" aria-label="Permalink to &quot;Spaces cannot be shared with themselves&quot;">​</a></h3><p>You entered your own address.</p>',64),e("h3",{email:"",id:"no-user-exists-with-the-e-mail",tabindex:"-1"},[r("No user exists with the e-mail "),e("a",{class:"header-anchor",href:"#no-user-exists-with-the-e-mail","aria-label":'Permalink to "No user exists with the e-mail {email}"'},"​")],-1),a('<p>There&#39;s no ApptiveGrid account for this address. Check the spelling; otherwise the person needs to <a href="/en/erste-schritte/konto-und-anmeldung#creating-an-account">register</a> first.</p><h3 id="exceeding-the-licensed-seats-on-your-plan" tabindex="-1">Exceeding the licensed seats on your plan <a class="header-anchor" href="#exceeding-the-licensed-seats-on-your-plan" aria-label="Permalink to &quot;Exceeding the licensed seats on your plan&quot;">​</a></h3><p>You&#39;ve invited more people with editing rights than you have seats for.</p><p><strong>Solution:</strong> Downgrade roles to <em>View</em> — that&#39;s free — or purchase additional seats. → <a href="/en/zusammenarbeit/sitzplaetze">Seats</a></p><hr><h2 id="flows" tabindex="-1">Flows <a class="header-anchor" href="#flows" aria-label="Permalink to &quot;Flows&quot;">​</a></h2><h3 id="flow-still-has-errors" tabindex="-1">Flow still has errors <a class="header-anchor" href="#flow-still-has-errors" aria-label="Permalink to &quot;Flow still has errors&quot;">​</a></h3><p>A step is incompletely configured. Go through the steps; the affected one is marked in the editor.</p><h3 id="no-previous-run-was-found" tabindex="-1">No previous run was found. <a class="header-anchor" href="#no-previous-run-was-found" aria-label="Permalink to &quot;No previous run was found.&quot;">​</a></h3><p>You want to start a Flow using the data from the last run, but there hasn&#39;t been one yet.</p><p><strong>Solution:</strong> Test it normally first. → <a href="/en/flows/testen">Testing Flows</a></p><h3 id="there-s-no-custom-ui-set-up-for-this-step-if-you-need-a-ui-you-can-add-it-in-the-flow-editor" tabindex="-1">There&#39;s no custom UI set up for this step. If you need a UI, you can add it in the Flow Editor. <a class="header-anchor" href="#there-s-no-custom-ui-set-up-for-this-step-if-you-need-a-ui-you-can-add-it-in-the-flow-editor" aria-label="Permalink to &quot;There&#39;s no custom UI set up for this step. If you need a UI, you can add it in the Flow Editor.&quot;">​</a></h3><p>A Flow step is meant to show a page, but none is assigned.</p><p><strong>Common cause:</strong> The assigned page was deleted. Check which page is set on the <em>Show page</em> step.</p><h3 id="this-process-step-could-not-be-loaded" tabindex="-1">This process step could not be loaded <a class="header-anchor" href="#this-process-step-could-not-be-loaded" aria-label="Permalink to &quot;This process step could not be loaded&quot;">​</a></h3><p>With the addition:</p><blockquote><p><em>The current step could not be executed due to a faulty configuration or an invalid value.</em></p><p><em>Please contact the person responsible for this process or your organization&#39;s administrator.</em></p></blockquote><p><strong>End users</strong> see this message. As the person responsible, check the <a href="/en/flows/durchlaufhistorie">run history</a> — under <em>Show error details</em> it shows which step failed.</p><h3 id="javascript-could-not-be-generated" tabindex="-1">JavaScript could not be generated <a class="header-anchor" href="#javascript-could-not-be-generated" aria-label="Permalink to &quot;JavaScript could not be generated&quot;">​</a></h3><p>AI generation in the JavaScript step failed. Refine the description and try again.</p><hr><h2 id="pages-and-portals" tabindex="-1">Pages and portals <a class="header-anchor" href="#pages-and-portals" aria-label="Permalink to &quot;Pages and portals&quot;">​</a></h2><h3 id="this-view-has-no-summable-numeric-columns" tabindex="-1">This view has no summable numeric columns <a class="header-anchor" href="#this-view-has-no-summable-numeric-columns" aria-label="Permalink to &quot;This view has no summable numeric columns&quot;">​</a></h3><p>The Sum Card needs a column of type <strong>Number</strong>, <strong>Decimal</strong>, or <strong>Currency</strong> in the embedded view.</p><p><strong>Common cause:</strong> The column exists but is hidden in this view.</p><h3 id="this-view-has-more-than-maxrows-rows-the-sum-only-covers-the-first-maxrows-rows" tabindex="-1">This view has more than {maxRows} rows. The sum only covers the first {maxRows} rows. <a class="header-anchor" href="#this-view-has-more-than-maxrows-rows-the-sum-only-covers-the-first-maxrows-rows" aria-label="Permalink to &quot;This view has more than {maxRows} rows. The sum only covers the first {maxRows} rows.&quot;">​</a></h3><p>Not an error, but important: the displayed sum is <strong>incomplete</strong>.</p><p><strong>Solution:</strong> For reliable totals, use a <a href="/en/ansichten/filtern-sortieren-gruppieren">grouping with an aggregate</a> or a field of type <a href="/en/grids/berechnete-felder">Calculate sum</a>.</p><h3 id="input-fields-without-a-name-or-id-are-not-included-in-the-flow-payload" tabindex="-1">Input fields without a name or id are not included in the Flow payload. <a class="header-anchor" href="#input-fields-without-a-name-or-id-are-not-included-in-the-flow-payload" aria-label="Permalink to &quot;Input fields without a name or id are not included in the Flow payload.&quot;">​</a></h3><p>Applies to the <em>HTML with form fields</em> block. Without a <code>name</code> or <code>id</code> attribute, the value is lost.</p><h3 id="count-file-s-could-not-be-uploaded" tabindex="-1">{count} file(s) could not be uploaded <a class="header-anchor" href="#count-file-s-could-not-be-uploaded" aria-label="Permalink to &quot;{count} file(s) could not be uploaded&quot;">​</a></h3><p>The most common cause is the plan-dependent size limit.</p><h3 id="preview-error" tabindex="-1">Preview error <a class="header-anchor" href="#preview-error" aria-label="Permalink to &quot;Preview error&quot;">​</a></h3><p>The HTML block contains faulty code.</p><hr><h2 id="forms-—-what-people-filling-them-out-see" tabindex="-1">Forms — what people filling them out see <a class="header-anchor" href="#forms-—-what-people-filling-them-out-see" aria-label="Permalink to &quot;Forms — what people filling them out see&quot;">​</a></h2><h3 id="oops-error" tabindex="-1">Oops - Error <a class="header-anchor" href="#oops-error" aria-label="Permalink to &quot;Oops - Error&quot;">​</a></h3><p>General error message on submission.</p><h3 id="warning-potentially-risky-form" tabindex="-1">Warning: Potentially risky form <a class="header-anchor" href="#warning-potentially-risky-form" aria-label="Permalink to &quot;Warning: Potentially risky form&quot;">​</a></h3><p>The form has been flagged as potentially abusive. <em>Open anyway</em> lets you continue.</p><p><strong>As the form creator:</strong> Contact <code>abuse@apptivegrid.com</code> to request a review.</p><h3 id="this-form-has-been-locked" tabindex="-1">This form has been locked <a class="header-anchor" href="#this-form-has-been-locked" aria-label="Permalink to &quot;This form has been locked&quot;">​</a></h3><p>The form has been locked. Also contact <code>abuse@apptivegrid.com</code>.</p><h3 id="never-reveal-your-password" tabindex="-1">Never reveal your password. <a class="header-anchor" href="#never-reveal-your-password" aria-label="Permalink to &quot;Never reveal your password.&quot;">​</a></h3><p>Not an error, but a security notice on every form. Never enter passwords or credentials in forms.</p><hr><h2 id="no-message-but-still-a-problem" tabindex="-1">No message, but still a problem <a class="header-anchor" href="#no-message-but-still-a-problem" aria-label="Permalink to &quot;No message, but still a problem&quot;">​</a></h2><p>Some things happen without any error message:</p><table tabindex="0"><thead><tr><th>Observation</th><th>Cause</th></tr></thead><tbody><tr><td>A button is missing</td><td>Missing permission → <a href="/en/fehlerbehebung/fehlende-schaltflaechen">I don&#39;t see a button</a></td></tr><tr><td>A Flow doesn&#39;t start</td><td>The trigger points to a different Grid or form</td></tr><tr><td>A Flow starts endlessly</td><td>An action writes to the Grid that triggers it</td></tr><tr><td>An entry has disappeared</td><td>It&#39;s excluded by the view&#39;s filter</td></tr><tr><td>A field is missing from the form</td><td>The column type has no form field, e.g. <em>Rich Text</em></td></tr><tr><td>A portal shows too much data</td><td>The embedded view isn&#39;t sufficiently filtered</td></tr><tr><td>A formula column stays empty</td><td>Typo in the expression → <a href="#expressions-and-formulas">Expressions and formulas</a></td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/fehlerbehebung/fehlende-schaltflaechen">I don&#39;t see a button</a></li><li><a href="/en/zusammenarbeit/rollen">Roles</a></li><li><a href="/en/referenz/glossar">Glossary</a></li></ul>',51)])])}const g=i(s,[["render",l]]);export{f as __pageData,g as default};
